$errors=[Collections.Generic.List[string]]::new()
function Eq($name,$actual,$expected){if($actual-ne$expected){$errors.Add("$name expected=$expected actual=$actual")}}
function Seq($name,$actual,$expected){if((@($actual)|ConvertTo-Json -Compress -Depth 30)-ne(@($expected)|ConvertTo-Json -Compress -Depth 30)){$errors.Add("$name sequence mismatch")}}
function Load($path){Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json}
